const LockPromotionCodeRedemptions = `-- name: LockPromotionCodeRedemptions :exec
SELECT pg_advisory_xact_lock(hashtextextended('promotion-code:' || $1::uuid::text || ':' || $2::uuid::text, 0))
`

type LockPromotionCodeRedemptionsParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	ID       uuid.UUID `json:"id"`
}

// Serializes, for the rest of the caller's transaction, the purchases one code
// grants without a payment, so two requests sent at once each see what the
// other committed before they count the code's redemptions and the reader's
// holdings. A purchase paid through a provider or a store is not held to it:
// its redemption is written whenever the payment is confirmed.
func (q *Queries) LockPromotionCodeRedemptions(ctx context.Context, arg LockPromotionCodeRedemptionsParams) error {
	_, err := q.db.ExecContext(ctx, LockPromotionCodeRedemptions, arg.TenantID, arg.ID)
	return err
}

const LockReaderPromotionGrants = `-- name: LockReaderPromotionGrants :exec
SELECT pg_advisory_xact_lock(hashtextextended('promotion-grant:' || $1::uuid::text || ':' || $2::uuid::text, 0))
`

type LockReaderPromotionGrantsParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	UserID   uuid.UUID `json:"user_id"`
}

// Serializes, for the rest of the caller's transaction, the purchases codes
// grant one reader without a payment, whichever code each names, so two
// requests sent at once with two codes that each make the same episode or
// volume free see what the other committed before they check what the reader
// holds. Taken before LockPromotionCodeRedemptions, always in that order.
func (q *Queries) LockReaderPromotionGrants(ctx context.Context, arg LockReaderPromotionGrantsParams) error {
	_, err := q.db.ExecContext(ctx, LockReaderPromotionGrants, arg.TenantID, arg.UserID)
	return err
}

const PromotionCodeTargetExists = `-- name: PromotionCodeTargetExists :one
SELECT CASE $1::text
        WHEN 'catalog' THEN TRUE
        WHEN 'label' THEN EXISTS (
            SELECT 1
            FROM labels l
            WHERE l.tenant_id = $2::uuid
                AND l.id = $3::uuid
        )
        WHEN 'series' THEN EXISTS (
            SELECT 1
            FROM series s
            WHERE s.tenant_id = $2::uuid
                AND s.id = $3::uuid
            FOR KEY SHARE OF s
        )
        WHEN 'volume' THEN EXISTS (
            SELECT 1
            FROM volumes v
            WHERE v.tenant_id = $2::uuid
                AND v.id = $3::uuid
        )
        WHEN 'episode' THEN EXISTS (
            SELECT 1
            FROM episodes e
            WHERE e.tenant_id = $2::uuid
                AND e.id = $3::uuid
        )
        ELSE FALSE
    END::boolean AS target_exists
`

type PromotionCodeTargetExistsParams struct {
	TargetKind string        `json:"target_kind"`
	TenantID   uuid.UUID     `json:"tenant_id"`
	TargetID   uuid.NullUUID `json:"target_id"`
}

// Whether the label, series, volume, or episode a new code names is one of
// the tenant's. The catalog is always there.
//
// A series is read under a key share lock, held until the code is committed:
// the code names its series by no foreign key, so the lock is what makes a
// DeleteSeries running at the same time either wait for the code and refuse,
// or delete the series first and leave nothing here to find.
func (q *Queries) PromotionCodeTargetExists(ctx context.Context, arg PromotionCodeTargetExistsParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, PromotionCodeTargetExists, arg.TargetKind, arg.TenantID, arg.TargetID)
	var target_exists bool
	err := row.Scan(&target_exists)
	return target_exists, err
}

const SetPromotionCodePaused = `-- name: SetPromotionCodePaused :exec
UPDATE promotion_codes
SET paused_at = CASE
        WHEN $1::boolean THEN COALESCE(paused_at, NOW())
    END,
    updated_at = NOW()
WHERE tenant_id = $2::uuid
    AND id = $3::uuid
`

type SetPromotionCodePausedParams struct {
	Paused   bool      `json:"paused"`
	TenantID uuid.UUID `json:"tenant_id"`
	ID       uuid.UUID `json:"id"`
}

// Pauses a code, keeping the instant it was first paused at, or resumes it.
func (q *Queries) SetPromotionCodePaused(ctx context.Context, arg SetPromotionCodePausedParams) error {
	_, err := q.db.ExecContext(ctx, SetPromotionCodePaused, arg.Paused, arg.TenantID, arg.ID)
	return err
}

const TenantHasLivePromotionCode = `-- name: TenantHasLivePromotionCode :one
SELECT EXISTS (
        SELECT 1
        FROM promotion_codes pc
        WHERE pc.tenant_id = $1::uuid
            AND pc.deleted_at IS NULL
            AND pc.paused_at IS NULL
            AND (
                pc.ends_at IS NULL
                OR pc.ends_at > NOW()
            )
    )::boolean AS has_live_code
`

// Whether the tenant holds a code a reader could enter now or later: one
// neither deleted, paused, nor past its end. A code whose window has not
// opened yet, or whose limits are spent, still counts, so the storefront
// offers the input no later than the code starts working.
func (q *Queries) TenantHasLivePromotionCode(ctx context.Context, tenantID uuid.UUID) (bool, error) {
	row := q.db.QueryRowContext(ctx, TenantHasLivePromotionCode, tenantID)
	var has_live_code bool
	err := row.Scan(&has_live_code)
	return has_live_code, err
}

const UpdatePromotionCodeLimits = `-- name: UpdatePromotionCodeLimits :exec
UPDATE promotion_codes
SET starts_at = $1::timestamptz,
    ends_at = $2::timestamptz,
    max_redemptions = $3::integer,
    max_redemptions_per_reader = $4::integer,
    updated_at = NOW()
WHERE tenant_id = $5::uuid
    AND id = $6::uuid
`

type UpdatePromotionCodeLimitsParams struct {
	StartsAt                sql.NullTime  `json:"starts_at"`
	EndsAt                  sql.NullTime  `json:"ends_at"`
	MaxRedemptions          sql.NullInt32 `json:"max_redemptions"`
	MaxRedemptionsPerReader sql.NullInt32 `json:"max_redemptions_per_reader"`
	TenantID                uuid.UUID     `json:"tenant_id"`
	ID                      uuid.UUID     `json:"id"`
}

// Changes what a code's tenant may change once it exists: when it works and
// how often it may be redeemed.
func (q *Queries) UpdatePromotionCodeLimits(ctx context.Context, arg UpdatePromotionCodeLimitsParams) error {
	_, err := q.db.ExecContext(ctx, UpdatePromotionCodeLimits,
		arg.StartsAt,
		arg.EndsAt,
		arg.MaxRedemptions,
		arg.MaxRedemptionsPerReader,
		arg.TenantID,
		arg.ID,
	)
	return err
}
